import 'package:code_builder/code_builder.dart';
import 'package:dart_style/dart_style.dart';
import 'package:pub_semver/pub_semver.dart';

import 'dart_string.dart';
import '../model/public_imports.dart';
import 'import_allocator.dart';

/// Writes the formatted source of a generated library or part file from
/// the Dart declarations of the constructs.
abstract final class LibraryWriter {
  /// The header of every generated file.
  static const header = '// GENERATED BY grund_generator. DO NOT EDIT.';

  /// A valid Dart package name; drivers check names against it too.
  static final validPackageName = RegExp(r'^[a-z_][a-z0-9_]*$');

  /// The source of a library of [packageName] holding [declarations], in
  /// order and separated by blank lines, formatted for [languageVersion].
  /// Its imports are prefixed by an [ImportAllocator] of its own, which
  /// imports a declaration of [publicImports] from its public library.
  ///
  /// Throws [ArgumentError] when [packageName] is not a valid Dart package
  /// name: it reaches a doc comment and import URLs.
  static String write({
    required String packageName,
    required Version languageVersion,
    required List<Spec> declarations,
    PublicImports publicImports = PublicImports.none,
  }) {
    if (!validPackageName.hasMatch(packageName)) {
      throw ArgumentError.value(
        packageName,
        'packageName',
        'must match ${validPackageName.pattern}',
      );
    }
    final library = Library(
      (b) => b
        ..comments.add(header.substring(3))
        ..docs.add(
          '/// Generated from the annotations of package:$packageName.',
        )
        ..body.addAll(_body(declarations)),
    );
    return _format(library, ImportAllocator(publicImports), languageVersion);
  }

  /// The source of a part file of the library at relative URI [partOf]
  /// holding [declarations]; it has no imports, so every reference is
  /// written as its bare name, in scope of the host library.
  static String writePart({
    required String partOf,
    required Version languageVersion,
    required List<Spec> declarations,
  }) {
    final part = Library(
      (b) => b
        ..comments.add(header.substring(3))
        ..directives.add(Directive.partOf(DartString.escape(partOf)))
        ..body.addAll(_body(declarations)),
    );
    return _format(part, Allocator.none, languageVersion);
  }

  static List<Spec> _body(List<Spec> declarations) => [
    for (final (index, declaration) in declarations.indexed) ...[
      if (index > 0) const Code('\n\n'),
      declaration,
    ],
  ];

  static String _format(Library library, Allocator allocator, Version version) {
    final emitter = DartEmitter(
      allocator: allocator,
      orderDirectives: true,
      useNullSafetySyntax: true,
    );
    final source = '${library.accept(emitter)}';
    return DartFormatter(languageVersion: version).format(source);
  }
}
